        self,
        x: torch.Tensor,
        pos_enc: torch.Tensor,
        mask: torch.Tensor,
        left_context: int = 0,
        right_context: int = 0,
    ) -> Tuple[torch.Tensor, torch.Tensor]:



        x = torch.cat([self.cache, x.transpose(1, 2)], dim=2)

        if right_context > 0:
            self.cache = x[:, :, -(self.lorder + right_context) : -right_context]
