def request_user_info(access_token: str = None) -> dict:
    ''' 
    '''
    if access_token is None:
        access_token = get_access_token()
    if access_token is None:
        raise KeyError()

    auth_server = Config()['auth']['oauth']['server_host']

    response = requests.get(
