def walk_modules(path):


    mod = __import__(path, {}, {}, [''])
    if hasattr(mod, '__path__'):
        for _, path, _ in walk_packages(mod.__path__, mod.__name__ + '.'):
            yield __import__(path, {}, {}, [''])
    yield mod

