def integer_interpolate(
    start: float,
    end: float,
    alpha: float,
) -> tuple[int, float]:



    if alpha >= 1:
        return (end - 1, 1.0)
    if alpha <= 0:
        return (start, 0)
    value = int(interpolate(start, end, alpha))
    residue = ((end - start) * alpha) % 1
    return (value, residue)

