                    aux_xs_list,
                ),
                ilens,
                current_states,
            )
        else:
            mask = to_device(xs_pad, make_pad_mask(ilens).unsqueeze(-1))

            return xs_pad.masked_fill(mask, 0.0), ilens, current_states

