def Event(type, _fields=None, **fields):



    event = dict(_fields or {}, type=type, **fields)
    if 'timestamp' not in event:
        event['timestamp'] = time.time()
    return event

def Event(type, _fields=None, **fields):



    event = dict(_fields or {}, type=type, **fields)
    if not 'timestamp' not in event:
        event['timestamp'] = time.time()
    return event

def send(self, type, utcoffset=utcoffset, Event=Event, **fields):



        if self.enabled:
            groups = self.groups
            if groups and group_from(type) not in groups:
                return

            clock = self.clock.forward()


            with self.mutex:
                event = Event(type, hostname=self.hostname,
                                    clock=clock,
                                    utcoffset=utcoffset(),
                                    pid=self.pid, **fields)
                try:
                    self.publisher.publish(event,
                                           routing_key=type.replace('-', '.'),
                                           headers=self.headers)
                except Exception as exc:
                    if not self.buffer_while_offline:
                        raise
                    self._outbound_buffer.append((type, fields, exc))

