def offset_line(x, xerr):



    if np.isscalar(xerr) or len(xerr) == len(x):
        xmin = x - xerr
        xmax = x + xerr
    elif len(xerr) == 2:
        xmin, xmax = x - xerr[0], x + xerr[1]
    return xmin, xmax

