def safe_asarray(X, dtype=None, order=None, copy=False, force_all_finite=True):

    if sparse.issparse(X):
        if copy:
            X = X.copy()
        if force_all_finite:
            _assert_all_finite(X.data)
        # enforces dtype on data array (order should be kept the same).
