        'request_protocol': os.environ.get("HTTPS") == "on" and "https" or "http",
        'settings': dict([(k, getattr(settings, k)) for k in dir(settings) if k.isupper()]),
    })
    return HttpResponseNotFound(t.render(c), mimetype='text/html')

