def track(
        self,
        sequence: Union[Iterable[ProgressType], Sequence[ProgressType]],
        total: int = None,
        task_id: Optional[TaskID] = None,
        description="Working...",
        update_period: float = 0.025,
    ) -> Iterable[ProgressType]:


        if total is None:
            if isinstance(sequence, Sized):
                task_total = len(sequence)
            else:
                raise ValueError(
                    f"unable to get size of {sequence!r}, please specify 'total'"
                )
        else:
            task_total = total

        if task_id is None:
            task_id = self.add_task(description, total=task_total)
        else:
            self.update(task_id, total=task_total)
        with self:
            advance = self.advance
            for values in iter_track(
                sequence,
                task_total,
                update_period=update_period if self.auto_refresh else 0,
            ):
                advance_total = 0
                for value in values:
                    yield value
                    advance_total += 1
                advance(task_id, advance_total)
                if not self.auto_refresh:
                    self.refresh()

