                for dev in devices_on_system:
                    cvid, pid, bcd = dev[:3]
                    if cvid == vid:
                        if pid in products:
                            if hasattr(cls.VENDOR_ID, 'keys'):
                                cbcd = cls.VENDOR_ID[vid][pid]
                            else:
                                cbcd = cls.BCD
                            if cls.test_bcd(bcd, cbcd):
                                if debug:
                                    cls.print_usb_device_info(dev)
                                if cls.can_handle(dev, debug=debug):
                                    return True
        return False

