def has_same_digits(num1: int, num2: int) -> bool:



    digits = [0] * 10

    while num1 > 0 and num2 > 0:
        digits[num1 % 10] += 1
        digits[num2 % 10] -= 1
        num1 //= 10
        num2 //= 10

    for digit in digits:
        if digit != 0:
            return False

    return True

