def migrate_config(fname: str) -> JSON_TYPE:

    config = load_yaml(fname)
    # Check if all views and cards have an id or else add one
    updated = False
    index = 0
    for view in config.get('views', []):
        if 'id' not in view:
            updated = True
            view.insert(0, 'id', index,
